/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    var payload = api.context.props.payload;
    if (api.context.props.payload.type.name == "Multi Card") {
        payload = api.context.props.payload.children[0];
    }

    return {
        propName: "currentScreenData",
        value: payload
    };
}

